#include <limits.h>
#include <stdio.h>

int main(void) {
    printf("char:      %zu byte,  %d to %d\n", sizeof(char), CHAR_MIN, CHAR_MAX);
    printf("short:     %zu bytes, %d to %d\n", sizeof(short), SHRT_MIN, SHRT_MAX);
    printf("int:       %zu bytes, %d to %d\n", sizeof(int), INT_MIN, INT_MAX);
    printf("long:      %zu bytes, %ld to %ld\n", sizeof(long), LONG_MIN, LONG_MAX);
    printf("long long: %zu bytes, %lld to %lld\n", sizeof(long long), LLONG_MIN, LLONG_MAX);
    printf("unsigned int max: %u\n", UINT_MAX);
    printf("bits in a char: %d\n", CHAR_BIT);
    return 0;
}

#include <stdio.h>

int main(void) {
    printf("%d %d %d\n", 0x1F, 0xff, 010);
    printf("%zu %zu %zu\n", sizeof(10), sizeof(10L), sizeof(10LL));
    printf("%u\n", 4000000000U);
    printf("%d\n", 'A' + 0x20);
    return 0;
}

#include <limits.h>
#include <stdio.h>

int main(void) {
    unsigned int u = UINT_MAX;
    u = u + 1;                  // wraps around to 0
    printf("%u\n", u);
    u = 0;
    u = u - 1;                  // wraps around to UINT_MAX
    printf("%u\n", u);

    unsigned char c = 250;
    c = c + 10;                 // 260 does not fit: 260 - 256 = 4
    printf("%d\n", c);
    return 0;
}

#include <stdio.h>

int main(void) {
    unsigned char x = 200;
    unsigned char y = 100;
    int sum = x + y;            // x and y are promoted to int first
    unsigned char small = x + y;
    printf("%d %d\n", sum, small);
    printf("%zu\n", sizeof(x + y));
    signed char s = -1;
    unsigned char t = s;        // -1 becomes 255
    printf("%d %d\n", s, t);
    return 0;
}

#include <stdio.h>

int main(void) {
    int a = -1;
    unsigned int b = 1;
    if (a < b) {
        puts("-1 < 1");
    } else {
        puts("-1 is NOT less than 1 ?!");
    }
    printf("%u\n", (unsigned int) a);
    return 0;
}

