#ifndef AREA_H
#define AREA_H

// area.h

long rect_area(int w, int h);

#endif

// area.c

#include "area.h"

long rect_area(int w, int h) {
    return (long) w * h;        // multiply as long, so the product does not overflow int
}

// main.c

#include <stdio.h>
#include "area.h"

int main(void) {
    printf("%ld\n", rect_area(3, 4));
    printf("%ld\n", rect_area(100000, 100000));
    return 0;
}

// commands:
// gcc -Wall -c area.c
// gcc -Wall -c main.c
// gcc -o main main.o area.o

