#include <limits.h>
#include <stdbool.h>
#include <stdio.h>

// returns true if a + b fits in an int (the addition would not overflow)
bool add_ok(int a, int b) {
    if (b > 0 && a > INT_MAX - b) {
        return false;           // a + b would be bigger than INT_MAX
    }
    if (b < 0 && a < INT_MIN - b) {
        return false;           // a + b would be smaller than INT_MIN
    }
    return true;
}

int main(void) {
    printf("%d\n", add_ok(INT_MAX, 1));
    printf("%d\n", add_ok(INT_MAX - 1, 1));
    printf("%d\n", add_ok(INT_MIN, -1));
    printf("%d\n", add_ok(-5, 7));
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: diffs n1 n2 ...\n");
        return 1;
    }
    long long prev = 0;
    for (int i = 1; i < argc; i++) {
        long long cur = atoll(argv[i]);
        printf("number: %lld\n", cur);
        if (cur == 0) {
            return 0;           // stop at the first 0
        }
        if (i > 1) {
            printf("difference = %lld\n", cur - prev);
        }
        prev = cur;
    }
    return 0;
}
